-- DRAFT foundation. Review and test in a disposable Supabase project before applying.
-- All client writes intentionally denied. Trusted services must validate membership,
-- parent ownership, consent authority and audit mutations transactionally.
begin;
create table public.tenants(id uuid primary key default gen_random_uuid(),name text not null,kind text not null check(kind in ('individual','organization','government')),created_at timestamptz not null default now());
create table public.memberships(tenant_id uuid references public.tenants(id),user_id uuid references auth.users(id),role text not null check(role in ('owner','manager','agronomist','viewer')),status text not null default 'active' check(status in ('active','suspended')),primary key(tenant_id,user_id));
create table public.organizations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,kind text not null check(kind in ('contract','government')),unique(tenant_id,id));
create table public.farms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,district text not null,area_ha numeric check(area_ha>=0),latitude numeric check(latitude between -90 and 90),longitude numeric check(longitude between -180 and 180),unique(tenant_id,id));
create table public.fields(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,farm_id uuid not null,name text not null,area_ha numeric check(area_ha>=0),crop text,foreign key(tenant_id,farm_id) references public.farms(tenant_id,id),unique(tenant_id,farm_id,id));
create table public.zones(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,farm_id uuid not null,field_id uuid not null,name text not null,foreign key(tenant_id,farm_id,field_id) references public.fields(tenant_id,farm_id,id),unique(tenant_id,farm_id,id));
create table public.devices(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,farm_id uuid not null,zone_id uuid not null,hardware_id text not null unique,connectivity text check(connectivity in ('wifi','mobile')),last_seen_at timestamptz,provisioning_status text not null default 'pending' check(provisioning_status in ('pending','active','retired')),foreign key(tenant_id,farm_id,zone_id) references public.zones(tenant_id,farm_id,id),unique(tenant_id,farm_id,id));
create table public.readings(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,farm_id uuid not null,device_id uuid not null,recorded_at timestamptz not null,received_at timestamptz not null default now(),sequence bigint not null check(sequence>=0),moisture_relative_pct numeric check(moisture_relative_pct between 0 and 100),temperature_c numeric,ec_ms_cm numeric check(ec_ms_cm>=0),battery_pct numeric check(battery_pct between 0 and 100),quality text not null check(quality in ('valid','uncalibrated','invalid')),foreign key(tenant_id,farm_id,device_id) references public.devices(tenant_id,farm_id,id),unique(device_id,recorded_at,sequence));
create index readings_history on public.readings(tenant_id,farm_id,device_id,recorded_at desc);
create table public.images(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,farm_id uuid not null,device_id uuid not null,captured_at timestamptz not null,object_path text not null unique,consent_required boolean not null default true,foreign key(tenant_id,farm_id,device_id) references public.devices(tenant_id,farm_id,id));
create table public.programs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,organization_id uuid not null,name text not null,district text not null,target_beneficiaries int check(target_beneficiaries>=0),starts_on date not null,ends_on date check(ends_on>=starts_on),foreign key(tenant_id,organization_id) references public.organizations(tenant_id,id),unique(tenant_id,id));
create table public.consents(id uuid primary key default gen_random_uuid(),owner_tenant_id uuid not null,farm_id uuid not null,grantee_tenant_id uuid not null references public.tenants(id),scopes text[] not null check(scopes <@ array['farm','readings','images','reports']::text[] and cardinality(scopes)>0),purpose text not null,granted_by uuid not null references auth.users(id),granted_at timestamptz not null default now(),expires_at timestamptz not null,revoked_at timestamptz,foreign key(owner_tenant_id,farm_id) references public.farms(tenant_id,id),check(owner_tenant_id<>grantee_tenant_id),check(expires_at>granted_at),unique(id,owner_tenant_id,farm_id,grantee_tenant_id));
create table public.enrollments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,program_id uuid not null,farm_id uuid not null,farm_tenant_id uuid not null,consent_id uuid not null,status text not null check(status in ('enrolled','withdrawn')),foreign key(tenant_id,program_id) references public.programs(tenant_id,id),foreign key(farm_tenant_id,farm_id) references public.farms(tenant_id,id),foreign key(consent_id,farm_tenant_id,farm_id,tenant_id) references public.consents(id,owner_tenant_id,farm_id,grantee_tenant_id),unique(program_id,farm_id));
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create function private.is_member(target uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.tenant_id=target and m.user_id=(select auth.uid()) and m.status='active')$$;
create function private.can_read_farm(owner_id uuid,farm uuid,scope_name text) returns boolean language sql stable security definer set search_path='' as $$select private.is_member(owner_id) or exists(select 1 from public.consents c where c.owner_tenant_id=owner_id and c.farm_id=farm and scope_name=any(c.scopes) and c.revoked_at is null and c.expires_at>now() and private.is_member(c.grantee_tenant_id))$$;
revoke all on function private.is_member(uuid),private.can_read_farm(uuid,uuid,text) from public;
grant execute on function private.is_member(uuid),private.can_read_farm(uuid,uuid,text) to authenticated;
alter table public.tenants enable row level security;
alter table public.memberships enable row level security;
alter table public.organizations enable row level security;
alter table public.farms enable row level security;
alter table public.fields enable row level security;
alter table public.zones enable row level security;
alter table public.devices enable row level security;
alter table public.readings enable row level security;
alter table public.images enable row level security;
alter table public.programs enable row level security;
alter table public.consents enable row level security;
alter table public.enrollments enable row level security;
create policy tenant_read on public.tenants for select to authenticated using(private.is_member(id));
create policy membership_read on public.memberships for select to authenticated using(user_id=(select auth.uid()) and private.is_member(tenant_id));
create policy organization_read on public.organizations for select to authenticated using(private.is_member(tenant_id));
create policy farm_read on public.farms for select to authenticated using(private.can_read_farm(tenant_id,id,'farm'));
create policy field_read on public.fields for select to authenticated using(private.can_read_farm(tenant_id,farm_id,'farm'));
create policy zone_read on public.zones for select to authenticated using(private.can_read_farm(tenant_id,farm_id,'farm'));
create policy device_read on public.devices for select to authenticated using(private.can_read_farm(tenant_id,farm_id,'readings'));
create policy reading_read on public.readings for select to authenticated using(private.can_read_farm(tenant_id,farm_id,'readings'));
create policy image_read on public.images for select to authenticated using(private.can_read_farm(tenant_id,farm_id,'images'));
create policy program_read on public.programs for select to authenticated using(private.is_member(tenant_id));
create policy consent_read on public.consents for select to authenticated using(private.is_member(owner_tenant_id) or private.is_member(grantee_tenant_id));
create policy enrollment_read on public.enrollments for select to authenticated using(private.is_member(farm_tenant_id) or (private.is_member(tenant_id) and private.can_read_farm(farm_tenant_id,farm_id,'farm')));
revoke all on public.tenants,public.memberships,public.organizations,public.farms,public.fields,public.zones,public.devices,public.readings,public.images,public.programs,public.consents,public.enrollments from anon,authenticated;
grant select on public.tenants,public.memberships,public.organizations,public.farms,public.fields,public.zones,public.devices,public.readings,public.images,public.programs,public.consents,public.enrollments to authenticated;
commit;
